import json

with open('/app/output/stats.json') as f:
    stats = json.load(f)
with open('/app/output/charts.json') as f:
    charts = json.load(f)

# Helper to format numbers
overview = stats['overview']

html = f'''<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
